import sys
import json
import os
from datetime import datetime, timezone

def validate_token(token_path):
    try:
        with open(token_path, 'r') as f:
            token_data = json.load(f)
    except (IOError, json.JSONDecodeError) as e:
        print(f"ERROR: Failed to read token file or parse JSON: {str(e)}", file=sys.stderr)
        sys.exit(2)

    required_fields = {'username', 'scopes', 'expires_at'}
    if not all(field in token_data for field in required_fields):
        print("ERROR: Token file missing required fields", file=sys.stderr)
        sys.exit(2)

    if not isinstance(token_data['scopes'], list) or not all(isinstance(scope, str) for scope in token_data['scopes']):
        print("ERROR: 'scopes' must be a list of strings", file=sys.stderr)
        sys.exit(2)

    if not isinstance(token_data['username'], str):
        print("ERROR: 'username' must be a string", file=sys.stderr)
        sys.exit(2)

    try:
        datetime.fromisoformat(token_data['expires_at'].replace('Z', '+00:00'))
    except ValueError:
        print("ERROR: 'expires_at' must be a valid ISO 8601 UTC timestamp", file=sys.stderr)
        sys.exit(2)

    return token_data

def main():
    if len(sys.argv) != 3:
        print("ERROR: Missing command-line arguments", file=sys.stderr)
        sys.exit(1)

    token_path = sys.argv[1]
    log_path = sys.argv[2]

    try:
        token_data = validate_token(token_path)
    except SystemExit:
        return

    requested_scope = sys.stdin.readline().strip() or ""
    username = sys.stdin.readline().strip() or ""

    current_time = datetime.now(timezone.utc)
    if current_time >= datetime.fromisoformat(token_data['expires_at'].replace('Z', '+00:00')):
        decision = "DENY"
    else:
        if requested_scope in token_data['scopes'] and username == token_data['username']:
            decision = "ALLOW"
        else:
            decision = "DENY"

    print(decision)

