import json
import sys
import os
from datetime import datetime, timezone

def validate_token(token_path):
    try:
        with open(token_path, 'r') as f:
            token_data = json.load(f)
    except (json.JSONDecodeError, IOError):
        print("ERROR: Invalid token file format or cannot read token file", file=sys.stderr)
        sys.exit(2)

    required_fields = {'username': str, 'scopes': list, 'expires_at': str}
    for field, expected_type in required_fields.items():
        if field not in token_data:
            print(f"ERROR: Missing required field '{field}' in token file", file=sys.stderr)
            sys.exit(2)
        if not isinstance(token_data[field], expected_type):
            print(f"ERROR: Invalid type for field '{field}' in token file", file=sys.stderr)
            sys.exit(2)

    return token_data

def main():
    if len(sys.argv) != 3:
        print("ERROR: Usage: python scope_gate.py <token_file> <log_file>", file=sys.stderr)
        sys.exit(1)

    token_path, log_path = sys.argv[1], sys.argv[2]
    token_data = validate_token(token_path)

    requested_scope = sys.stdin.readline().strip()
    username = sys.stdin.readline().strip()

    current_time = datetime.now(timezone.utc).isoformat() + 'Z'
    if current_time >= token_data['expires_at']:
        decision = 'DENY'
    else:
        if requested_scope in token_data['scopes'] and username == token_data['username']:
            decision = 'ALLOW'
        else:
            decision = 'DENY'

    print(decision)

    try:
        with open(log_path, 'a') as f:
            log_entry = f"{current_time} {token_data['username']} {requested_scope} {decision}\n"
            f.write(log_entry)
    except IOError:
        print("ERROR: Cannot write to log file", file=sys.stderr)
        sys.exit(3)

if __name__ == "__main__":
    main()
